Edit the given code to use dynamic programming to solve the problem.

def rod_cutting(arr, n):
    if n <= 0:
        return 0
    max_val = 0
    for i in range(0, n):
        max_val = max(max_val, arr[i] + rod_cutting(arr, n-i-1))
    return max_val

